package relayer

import (
	"context"
	"errors"
	"math/big"
	"strings"
	"testing"
	"time"

	"github.com/ethereum/go-ethereum"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/stretchr/testify/assert"
)

type mockConfirmer struct {
	receiptErr     error
	blockNumberErr error
}

var (
	notFoundTxHash = common.HexToHash("0x123")
	succeedTxHash  = common.HexToHash("0x456")
	// failTxHash     = common.HexToHash("0x789")
	blockNum = 10
)

func (m *mockConfirmer) TransactionReceipt(ctx context.Context, txHash common.Hash) (*types.Receipt, error) {
	if m.receiptErr != nil {
		return nil, m.receiptErr
	}

	if txHash == notFoundTxHash {
		return nil, ethereum.NotFound
	}

	if txHash == succeedTxHash {
		return &types.Receipt{
			Status:      types.ReceiptStatusSuccessful,
			BlockNumber: new(big.Int).Sub(big.NewInt(int64(blockNum)), big.NewInt(1)),
		}, nil
	}

	return &types.Receipt{
		Status:      types.ReceiptStatusFailed,
		BlockNumber: big.NewInt(1),
	}, nil
}

func (m *mockConfirmer) BlockNumber(ctx context.Context) (uint64, error) {
	if m.blockNumberErr != nil {
		return 0, m.blockNumberErr
	}

	return uint64(blockNum), nil
}

func Test_WaitReceipt(t *testing.T) {
	timeoutTicker, cancel := context.WithTimeout(context.Background(), time.Duration(2*time.Second))
	defer cancel()

	tests := []struct {
		name        string
		ctx         context.Context
		txHash      common.Hash
		wantErr     error
		wantReceipt *types.Receipt
	}{
		{
			"success",
			context.Background(),
			succeedTxHash,
			nil,
			&types.Receipt{
				Status:      types.ReceiptStatusSuccessful,
				BlockNumber: new(big.Int).Sub(big.NewInt(int64(blockNum)), big.NewInt(1)),
			},
		},
		// {
		// 	"receiptStatusUnsuccessful",
		// 	context.Background(),
		// 	failTxHash,
		// 	fmt.Errorf("transaction reverted, hash: %s", failTxHash),
		// 	nil,
		// },
		{
			"ticker timeout",
			timeoutTicker,
			notFoundTxHash,
			errors.New("context deadline exceeded"),
			nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			receipt, err := WaitReceipt(tt.ctx, &mockConfirmer{}, tt.txHash)
			if tt.wantErr != nil {
				assert.EqualError(t, err, tt.wantErr.Error())
			} else {
				assert.Nil(t, err)
			}

			assert.Equal(t, tt.wantReceipt, receipt)
		})
	}
}

func Test_WaitConfirmations(t *testing.T) {
	timeoutTicker, cancel := context.WithTimeout(context.Background(), time.Duration(2*time.Second))
	defer cancel()

	tests := []struct {
		name      string
		ctx       context.Context
		timeout   time.Duration
		confirmer *mockConfirmer
		confs     uint64
		txHash    common.Hash
		wantErr   error
	}{
		{
			"success",
			context.Background(),
			0,
			&mockConfirmer{},
			1,
			succeedTxHash,
			nil,
		},
		{
			"ticker timeout",
			timeoutTicker,
			0,
			&mockConfirmer{},
			1,
			notFoundTxHash,
			errors.New("context deadline exceeded"),
		},
		{
			// the receipt sits one block behind the latest, so asking for more
			// confirmations than there are blocks can never be satisfied and the
			// wait has to keep polling until the context gives out.
			"still waiting when the confirmations are short",
			context.Background(),
			100 * time.Millisecond,
			&mockConfirmer{},
			uint64(blockNum) + 1,
			succeedTxHash,
			errors.New("context deadline exceeded"),
		},
		{
			// a broken client is neither NotFound nor "still waiting", so it has to
			// surface instead of being waited out.
			"receipt lookup error",
			context.Background(),
			0,
			&mockConfirmer{receiptErr: errors.New("receipt lookup failed")},
			1,
			succeedTxHash,
			errors.New("receipt lookup failed"),
		},
		{
			"block number lookup error",
			context.Background(),
			0,
			&mockConfirmer{blockNumberErr: errors.New("block number lookup failed")},
			1,
			succeedTxHash,
			errors.New("block number lookup failed"),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ctx := tt.ctx

			if tt.timeout > 0 {
				var cancel context.CancelFunc

				ctx, cancel = context.WithTimeout(context.Background(), tt.timeout)
				defer cancel()
			}

			err := WaitConfirmations(ctx, tt.confirmer, tt.confs, tt.txHash)
			if tt.wantErr != nil {
				assert.EqualError(t, err, tt.wantErr.Error())
			} else {
				assert.Nil(t, err)
			}
		})
	}
}

type decodeMessageDataCase struct {
	name               string
	eventData          []byte
	value              *big.Int
	wantEventType      EventType
	wantCanonicalToken CanonicalToken
	wantAmount         *big.Int
	wantError          error
}

func decodeMessageDataCases() []decodeMessageDataCase {
	amount20, _ := new(big.Int).SetString("20000000000000000000", 10)
	amountUSDC, _ := new(big.Int).SetString("18200000000", 10)

	return []decodeMessageDataCase{
		{
			"onMessageInvocationERC20Vault",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC20,
			CanonicalERC20{
				ChainId:  167001, // 28c59
				Addr:     common.HexToAddress("0x6e7cfe3fd749F6E1C53BC1065fc702eb6c22F600"),
				Decimals: uint8(18), // 12
				Symbol:   "TEST",
				Name:     "TestERC20",
			},
			amount20,
			nil,
		},
		{
			"onMessageInvocationERC721Vault",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC721,
			CanonicalNFT{
				ChainId: 167001, // 28c59
				Addr:    common.HexToAddress("0x6e7cfe3fd749F6E1C53BC1065fc702eb6c22F600"),
				Symbol:  "TEST",
				Name:    "TestERC20",
			},
			big.NewInt(1),
			nil,
		},
		{
			"onMessageInvocationERC1155Vault",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC1155,
			CanonicalNFT{
				ChainId: 167001, // 28c59
				Addr:    common.HexToAddress("0x6e7cfe3fd749F6E1C53BC1065fc702eb6c22F600"),
				Symbol:  "TEST",
				Name:    "TestERC20",
			},
			big.NewInt(7),
			nil,
		},
		{
			// Real mainnet ERC1155 send (msgHash
			// 0xf1f46c6959d8b1ee024a9ce8a18db6883c66c93a8ff466bed52ded2ee7d064fe): one unit of token
			// id 7, whose canonical contract exposes neither name() nor symbol(), so both strings
			// are empty. That is what lets the ERC20 layout decode without erroring - it reads the
			// symbol head (128) as `decimals` and the tokenIds array offset (0x160) as the amount.
			"onMessageInvocationERC1155VaultEmptySymbolAndName",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC1155,
			CanonicalNFT{
				ChainId: 1,
				Addr:    common.HexToAddress("0x1F8483664620ff1278f4C1b0d11e4D7dAa11a035"),
				Symbol:  "",
				Name:    "",
			},
			big.NewInt(1),
			nil,
		},
		{
			// Real mainnet ERC20 send, so the layout check is exercised against a payload that must
			// keep decoding as ERC20: same four head words as an ERC721 send, told apart only by
			// the canonical tuple carrying `decimals` where CanonicalNFT carries the symbol head.
			"onMessageInvocationERC20VaultMainnet",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC20,
			CanonicalERC20{
				ChainId:  167_000,
				Addr:     common.HexToAddress("0x19e26B0638bf63aa9fa4d14c6baF8D52eBE86C5C"),
				Decimals: uint8(6),
				Symbol:   "USDC.e",
				Name:     "Bridged USDC (Stargate)",
			},
			amountUSDC,
			nil,
		},
		{
			// The ERC721 half of the same trap: four head words like an ERC20 send, and with both
			// canonical strings empty the ERC20 layout decodes without erroring.
			"onMessageInvocationERC721VaultEmptySymbolAndName",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC721,
			CanonicalNFT{
				ChainId: 1,
				Addr:    common.HexToAddress("0x1F8483664620ff1278f4C1b0d11e4D7dAa11a035"),
				Symbol:  "",
				Name:    "",
			},
			big.NewInt(1),
			nil,
		},
		{
			// Real mainnet ERC721 send (msgHash
			// 0x25742dc1ceb54feee813482b3bee4b928829c48f8b6e17145e2320ead12bf087), Doodles Penguin
			// #14. Shares its four head words with an ERC20 send, so it pins that the two are
			// separated by the payload's shape and not by which decoder is attempted first.
			"onMessageInvocationERC721VaultMainnet",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC721,
			CanonicalNFT{
				ChainId: 1,
				Addr:    common.HexToAddress("0x0C0f49B8EFc5a2DDeb34E1f6F51292Efa0A6CC7A"),
				Symbol:  "DOODLEPENGS",
				Name:    "Doodles Penguin",
			},
			big.NewInt(1),
			nil,
		},
		{
			// A canonical ERC20 whose `decimals` is 128, which is where CanonicalNFT keeps the head
			// offset of `symbol`. Anyone can deploy such a token - ERC20Vault fills the field from
			// `_safeDecimals(token)` - so a decoder that separates the two layouts by that single
			// word alone hands an attacker an ERC721 classification and, with it, a skipped quota
			// check. Only the encoding as a whole tells them apart.
			"onMessageInvocationERC20VaultWith128Decimals",
			// nolint lll
			common.Hex2Bytes(""),
			nil,
			EventTypeSendERC20,
			CanonicalERC20{
				ChainId:  167_001,
				Addr:     common.HexToAddress("0x6e7cfe3fd749F6E1C53BC1065fc702eb6c22F600"),
				Decimals: uint8(128),
				Symbol:   "TEST",
				Name:     strings.Repeat("N", 100),
			},
			big.NewInt(999),
			nil,
		},
		{
			// ERC1155-shaped, but the amounts array points past the end of the payload. Message
			// data is attacker-supplied - Bridge.sendMessage is permissionless - so this must be
			// reported as an unrecognised payload rather than read at that offset.
			"onMessageInvocationERC1155VaultAmountsOffsetOutOfRange",
			// nolint lll
			common.Hex2Bytes(""),
			big.NewInt(0),
			EventTypeSendETH,
			nil,
			big.NewInt(0),
			nil,
		},
		{
			"nilData",
			common.Hex2Bytes("00"),
			big.NewInt(1),
			EventTypeSendETH,
			nil,
			big.NewInt(1),
			nil,
		},
	}
}

// FuzzDecodeMessageData feeds mutated payloads through the decoder. Bridge.sendMessage is
// permissionless, so `Message.Data` is attacker-supplied and reaches this function straight from
// the indexer, where nothing recovers a panic. Decoding must therefore always return, whatever the
// bytes are. Seeded from the table above, which carries the real mainnet payloads.
func FuzzDecodeMessageData(f *testing.F) {
	for _, tt := range decodeMessageDataCases() {
		f.Add(tt.eventData)
	}

	f.Fuzz(func(t *testing.T, eventData []byte) {
		eventType, _, amount, err := DecodeMessageData(eventData, big.NewInt(0))

		// An unrecognised payload is an ETH bridge, never an error and never a nil amount: both
		// callers dereference what comes back.
		if err == nil && amount == nil {
			t.Fatalf("nil amount for eventType ' + '%v' + '", eventType)
		}
	})
}

func Test_DecodeMessageSentData(t *testing.T) {
	for _, tt := range decodeMessageDataCases() {
		t.Run(tt.name, func(t *testing.T) {
			eventType, canonicalToken, amount, err := DecodeMessageData(tt.eventData, tt.value)

			assert.Equal(t, tt.wantEventType, eventType)
			assert.Equal(t, tt.wantCanonicalToken, canonicalToken)
			assert.Equal(t, tt.wantAmount, amount)
			assert.Equal(t, tt.wantError, err)
		})
	}
}
